from taf.fdsw.rc.schemas.base import SchemaField, SchemaObject


class ManagementPlaneParameters(SchemaObject):
    ip_address = SchemaField(name="ipAddress")
    prefix_length = SchemaField(name="prefixLength")
    gateway = SchemaField(name="gateway")
    vlan_id = SchemaField(name="vlanId")
    oms_ip_address = SchemaField(name="omsIpAddress")
    sec_ip_address = SchemaField(name="secIpAddress")
    sec_prefix_length = SchemaField(name="secPrefixLength")
    sec_vlan_id = SchemaField(name="secVlanId")
    sec_gateway = SchemaField(name="secGateway")

    def __init__(self, ip_address, prefix_length, gateway, vlan_id, oms_ip_address, sec_ip_address, sec_prefix_length, sec_vlan_id, sec_gateway):
        self.ip_address = ip_address
        self.prefix_length = prefix_length
        self.gateway = gateway
        self.vlan_id = vlan_id
        self.oms_ip_address = oms_ip_address
        self.sec_ip_address = sec_ip_address
        self.sec_prefix_length = sec_prefix_length
        self.sec_vlan_id = sec_vlan_id
        self.sec_gateway = sec_gateway

        super(ManagementPlaneParameters, self).__init__()


class CertificateServerParameters(SchemaObject):
    directory = SchemaField(name="directory")
    ip_address = SchemaField(name="ipAddress")
    subject_name = SchemaField(name="subjectName")
    vpn_gateway_ip_address = SchemaField(name="vpnGatewayIpAddress")
    server_port = SchemaField(name="serverPort")

    def __init__(self, directory, ip_address, subject_name, vpn_gateway_ip_address, server_port):
        self.directory = directory
        self.ip_address = ip_address
        self.subject_name = subject_name
        self.vpn_gateway_ip_address = vpn_gateway_ip_address
        self.server_port = server_port
        super(CertificateServerParameters, self).__init__()


class AutoConnection(SchemaObject):
    auto_configuration_mode = SchemaField(name="autoConfigurationMode")
    management_plane_parameters = SchemaField(name="managementPlaneParameters", klass=ManagementPlaneParameters)
    certificate_server_parameters = SchemaField(name="certificateServerParameters", klass=CertificateServerParameters)

    def __init__(self, auto_configuration_mode, management_plane_parameters, certificate_server_parameters):
        super(AutoConnection, self).__init__()
        self.auto_configuration_mode = auto_configuration_mode
        self.management_plane_parameters = management_plane_parameters
        self.certificate_server_parameters = certificate_server_parameters


class Site_Identification18A(SchemaObject):
    bts_id = SchemaField(name="btsId")
    site_id = SchemaField(name="siteId")
    serial_number = SchemaField(name="serialNumber")
    module_version = SchemaField(name="moduleVersion")
    coordinates = SchemaField(name="coordinates")

    def __init__(self, bts_id, site_id, serial_number, module_version, coordinates):
        self.bts_id = bts_id
        self.site_id = site_id
        self.serial_number = serial_number
        self.module_version = module_version
        self.coordinates = coordinates
        super(Site_Identification18A, self).__init__()
